    TypeTracker getACompatibleTypeTracker() {
      exists(boolean hasCall, ContentOption c |
        result = MkTypeTracker(hasCall, c) and
        (
          c.isNone() and content.isNone()
          or
          compatibleContents(c.asSome(), content.asSome())
